declare(strict_types=1);
require_once __DIR__.'/manufacturing.php';

function preparationUpgrade(array $s,array $c,array $o):array{
 if((int)($s['schema']??1)>=2)return preparationProjectItems($s,$c,$o);$tranches=[];
 foreach($s['items']??[] as $v){$base=['variant_id'=>$v['id'],'source_kind'=>'legacy','source_ref'=>'','source'=>$s['source']??'Прежняя комплектация','unit'=>$s['unit']??'комплект','composition'=>'Полный комплект для изделия','model'=>$o['product'],'pattern_version'=>'Прежние подтверждённые сведения','cancelled_quantity'=>0,'cancelled'=>false];
  if((int)$v['ready'])$tranches[]=$base+['id'=>'legacy-ready-'.$v['id'],'promised'=>(int)$v['ready'],'received'=>(int)$v['ready'],'expected_at'=>null];if((int)$v['expected'])$tranches[]=$base+['id'=>'legacy-expected-'.$v['id'],'promised'=>(int)$v['expected'],'received'=>0,'expected_at'=>($v['ready_date']??$o['start_date']).' 00:00:00'];
 }
 $s['schema']=2;$s['tranches']=$tranches;$s['cost_source']='manual';$s['manual_cost_cents']=$s['cost_cents']??null;$s['cost_complete']=($s['cost_mode']??'unknown')!=='unknown';return preparationProjectItems($s,$c,$o);
}
function preparationBalances(array $c,array $o):array{
 $out=[];$issues=[];if(!manufacturingAvailable())return $out;foreach(rows('SELECT tranche_id,batch_key,kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=?',[$c['id'],$o['id']]) as $m){$id=$m['tranche_id'];$out[$id]??=['issued'=>0,'reserved'=>0,'planned'=>0];$q=(int)$m['quantity'];if($m['kind']==='issue'){$out[$id]['issued']+=$q;$out[$id]['reserved']-=$q;$issues[$m['batch_key']]=($issues[$m['batch_key']]??0)+$q;}elseif($m['kind']==='reserve')$out[$id]['reserved']+=$q;elseif($m['kind']==='unreserve')$out[$id]['reserved']-=$q;elseif($m['kind']==='plan_reserve')$out[$id]['planned']+=$q;elseif($m['kind']==='unplan')$out[$id]['planned']-=$q;}
 // Earlier releases remain facts. Project their consumption without rewriting them.
 $batches=[];foreach(rows("SELECT released,dependencies,planning_meta FROM tasks WHERE company_id=? AND order_id=? AND state<>'cancelled' AND released>0",[$c['id'],$o['id']]) as $t){if(decode($t['dependencies']))continue;$m=decode($t['planning_meta']??null);$key=$m['batch_id']??'legacy-'.$o['id'];$batches[$key]=['quantity'=>max($batches[$key]['quantity']??0,(int)$t['released']),'variant'=>$m['variant_id']??'variant-main'];}
 $stored=preparationRecord($c,$o)['state']??preparationDefault($c,$o);$lots=$stored['tranches']??array_map(fn($v)=>['id'=>'legacy-ready-'.$v['id'],'variant_id'=>$v['id'],'received'=>$v['ready']],$stored['items']??[]);
 foreach($batches as $batch=>$b){$remaining=max(0,$b['quantity']-($issues[$batch]??0));foreach($lots as $lot){if($b['variant']!=='variant-main'&&$b['variant']!==$lot['variant_id'])continue;$out[$lot['id']]??=['issued'=>0,'reserved'=>0,'planned'=>0];$take=min($remaining,max(0,$lot['received']-$out[$lot['id']]['issued']));$out[$lot['id']]['issued']+=$take;$remaining-=$take;if(!$remaining)break;}}
 foreach($out as &$b){$b['reserved']=max(0,$b['reserved']);$b['planned']=max(0,$b['planned']);}unset($b);return $out;
}
function preparationProjectItems(array $s,array $c,array $o):array{
 $balance=preparationBalances($c,$o);$items=[];foreach(goalVariants($o) as $v)$items[$v['id']]=$v+['ready'=>0,'expected'=>0,'ready_date'=>null,'free'=>0,'reserved'=>0,'issued'=>0];
 $tranches=$s['tranches']??[];foreach($tranches as &$t){$b=$balance[$t['id']]??['issued'=>0,'reserved'=>0,'planned'=>0];$received=(int)($t['received']??0);$expected=empty($t['cancelled'])?max(0,(int)$t['promised']-$received-(int)($t['cancelled_quantity']??0)):0;$t['expected']=$expected;$t['issued']=$b['issued'];$t['reserved']=$b['reserved'];$t['planned_reserved']=$b['planned'];$t['free']=max(0,$received-$b['issued']-$b['reserved']);$id=$t['variant_id'];if(!isset($items[$id]))continue;$items[$id]['ready']+=$received;$items[$id]['expected']+=$expected;$items[$id]['free']+=$t['free'];$items[$id]['reserved']+=$b['reserved'];$items[$id]['issued']+=$b['issued'];if($expected&&$t['expected_at'])$items[$id]['ready_date']=max($items[$id]['ready_date']??'',substr($t['expected_at'],0,10));}unset($t);
 $s['tranches']=$tranches;$s['items']=array_values($items);return $s;
}
function preparationFreeForVariant(array $c,array $o,string $variant):int{$s=preparationState($c,$o);foreach($s['items'] as $v)if($v['id']===$variant)return (int)($v['free']??$v['ready']);return 0;}
function preparationNormalizeTranches(array $s,array $c,array $o,array $old):array{
 $out=$old;$out['schema']=2;$out['source']=textField($s,'source',1000,true);$out['department_id']=textField($s,'department_id',60);$out['unit']=textField($s,'unit',40,true);if($out['department_id']){$w=array_column($c['passport']['structure']['workshops']??[],null,'id')[$out['department_id']]??null;if(!$w||($w['kind']??'')!=='preparation')fail('Выберите подразделение подготовки');}
 $out['tranches']=[];$seen=[];$variants=array_column(goalVariants($o),null,'id');$oldMap=array_column($old['tranches']??[],null,'id');$balances=preparationBalances($c,$o);$sum=[];
 if(count($s['tranches']??[])>3000)fail('Слишком много поступлений');foreach($s['tranches']??[] as $t){$id=manufacturingId($t);if(isset($seen[$id]))fail('Повтор кода поступления');$seen[$id]=true;$prior=$oldMap[$id]??null;if(($prior['source_kind']??'')==='cutting'){$out['tranches'][]=$prior;continue;}$variant=manufacturingId($t,'variant_id',60);if(!isset($variants[$variant]))fail('Поступление относится к отсутствующему варианту цели');$promised=numberField($t,'promised',0,100000);$received=(int)($prior['received']??0);$cancelled=(bool)($t['cancelled']??false);$used=($balances[$id]['issued']??0)+($balances[$id]['reserved']??0);if($promised<$received||$received<$used)fail('Нельзя уменьшить поступление ниже факта или использованного количества');if($prior&&$received>0&&$variant!==$prior['variant_id'])fail('Вариант принятого поступления не меняется');$kind=$prior['source_kind']??($t['source_kind']??'manual');if(!in_array($kind,['manual','external','warehouse','legacy'],true))fail('Расчётный крой создаётся только модулем раскроя');$at=empty($t['expected_at'])?null:textField($t,'expected_at',30,true);if(!$cancelled&&$promised>$received&&!$at)fail('Для ожидаемого остатка укажите дату и время');if($at)manufacturingTimestamp($at,$c['passport']['timezone']);
  $row=['id'=>$id,'variant_id'=>$variant,'source_kind'=>$kind,'source_ref'=>textField($t,'source_ref',100),'source'=>textField($t,'source',1000,true),'unit'=>$out['unit'],'composition'=>textField($t,'composition',1000,true),'model'=>$o['product'],'pattern_version'=>textField($t,'pattern_version',100,true),'promised'=>$promised,'received'=>$received,'expected_at'=>$at,'cancelled'=>$cancelled,'cancelled_quantity'=>$prior['cancelled_quantity']??0];
  if($kind==='warehouse'&&!$row['source_ref'])fail('Для склада укажите постоянный код физической партии');if($kind==='warehouse'){foreach(rows('SELECT order_id,state_json FROM order_preparations WHERE company_id=? AND order_id<>?',[$c['id'],$o['id']]) as $other)foreach(decode($other['state_json'])['tranches']??[] as $lot)if(($lot['source_kind']??'')==='warehouse'&&($lot['source_ref']??'')===$row['source_ref']&&empty($lot['cancelled']))fail('Эта физическая складская партия уже закреплена за другой целью');}
  $out['tranches'][]=$row;$sum[$variant]=($sum[$variant]??0)+($cancelled?$received:$promised);
 }
 foreach($oldMap as $id=>$t)if(!isset($seen[$id])){if(($t['source_kind']??'')==='cutting')$out['tranches'][]=$t;elseif(($t['received']??0)>0||($balances[$id]['issued']??0)>0||($balances[$id]['reserved']??0)>0)fail('Принятое или зарезервированное поступление сохраняется в истории');}
 foreach($out['tranches'] as $t)if(($t['source_kind']??'')==='cutting')$sum[$t['variant_id']]=($sum[$t['variant_id']]??0)+(empty($t['cancelled'])?$t['promised']:$t['received']);foreach($sum as $id=>$n)if($n>(int)$variants[$id]['quantity'])fail('Обеспечение варианта превышает заказ');
 if($c['role']==='owner'){$out['cost_source']=$s['cost_source']??'manual';if(!in_array($out['cost_source'],['manual','detailed','combined'],true))fail('Выберите источник стоимости');$out['cost_mode']=$s['cost_mode']??'unknown';if(!in_array($out['cost_mode'],['unknown','amount','included','customer'],true))fail('Выберите основание стоимости');$out['manual_cost_cents']=numberField($s,'manual_cost_cents',0,100000000000,true);}
 return preparationProjectItems($out,$c,$o);
}
function preparationCosts(array $s,array $c,array $o):array{
 $sum=0;$complete=true;$details=[];if(manufacturingAvailable())foreach(rows("SELECT id,calculation_json FROM cutting_plans WHERE company_id=? AND order_id=? AND status IN ('released','in_progress','completed')",[$c['id'],$o['id']]) as $p){$calc=decode($p['calculation_json']);$fund=$calc['pay']['fund_cents']??null;$material=$o['material_owner']==='customer'?0:($calc['material_cents']??null);if($fund===null||$material===null)$complete=false;$sum+=($fund??0)+($material??0);$details[]=['plan_id'=>$p['id'],'fund_cents'=>$fund,'material_cents'=>$material];}
 $source=$s['cost_source']??'manual';$manual=$s['manual_cost_cents']??$s['cost_cents']??null;if($source==='manual'){$total=($s['cost_mode']??'unknown')==='amount'?$manual:null;$complete=($s['cost_mode']??'unknown')!=='unknown'&&(($s['cost_mode']??'')!=='amount'||$manual!==null);}
 else{$total=$sum;if(!$details)$complete=false;if($source==='combined'){if($manual===null)$complete=false;$total+=$manual??0;}$s['cost_mode']='amount';}
 if($source!=='manual'&&array_sum(array_map(fn($v)=>(int)$v['ready']+(int)$v['expected'],$s['items']??[]))<(int)$o['quantity'])$complete=false;$s['cost_cents']=$total;$s['cost_complete']=$complete;$s['cutting_costs']=$details;$s['cost_explanation']=$source==='manual'?'Ручной итог уже включает раскрой; подробные фонды повторно не добавляются':($source==='combined'?'Подробный раскрой плюс отдельно подтверждённые дополнительные затраты':'Подробные расчёты раскроя; каждая волна учитывается один раз');return $s;
}
function preparationPersist(array $c,array $o,array $s,?array $record):array{
 $s=preparationCosts(preparationProjectItems($s,$c,$o),$c,$o);$id=$record['id']??uid();$rev=($record['revision']??0)+1;if($record)query('UPDATE order_preparations SET state_json=?,revision=?,actor_id=? WHERE id=? AND company_id=?',[j($s),$rev,$_SESSION['user_id'],$id,$c['id']]);else query('INSERT INTO order_preparations (id,company_id,order_id,revision,state_json,actor_id) VALUES (?,?,?,?,?,?)',[$id,$c['id'],$o['id'],$rev,j($s),$_SESSION['user_id']]);query('INSERT INTO preparation_revisions (id,preparation_id,company_id,revision,state_json,actor_id) VALUES (?,?,?,?,?,?)',[uid(),$id,$c['id'],$rev,j($s),$_SESSION['user_id']]);$expenses=array_values(array_filter(is_array($o['expenses'])?$o['expenses']:decode($o['expenses']),fn($e)=>($e['id']??'')!=='preparation-cost'));if($s['cost_mode']==='amount'&&$s['cost_cents']!==null)$expenses[]=['id'=>'preparation-cost','name'=>'Подготовка и раскрой · единый источник','kind'=>'direct','cents'=>$s['cost_cents']];query('UPDATE orders SET expenses=?,revision=revision+1 WHERE id=? AND company_id=?',[j($expenses),$o['id'],$c['id']]);audit('preparation_saved',['order_id'=>$o['id'],'revision'=>$rev,'source'=>$s['cost_source']??'manual']);return ['saved'=>true,'revision'=>$rev,'order_revision'=>(int)$o['revision']+1,'preparation'=>['id'=>$id,'revision'=>$rev,'state'=>$s]];
}
function preparationMovement(array $c,array $o,string $lot,string $batch,string $kind,int $quantity,array $details=[]):void{
 if($quantity<=0)return;query('INSERT INTO preparation_movements (id,company_id,order_id,tranche_id,batch_key,kind,quantity,state_json,actor_id) VALUES (?,?,?,?,?,?,?,?,?)',[uid(),$c['id'],$o['id'],$lot,$batch,$kind,$quantity,j($details),$_SESSION['user_id']]);
}
function preparationTrancheSupply(array $s,array $c,array $o,array $covered,int $start):array{
 $s=preparationUpgrade($s,$c,$o);if(isset($covered['variant-main'])&&!in_array('variant-main',array_column($s['items'],'id'),true)){$rest=$covered['variant-main'];unset($covered['variant-main']);foreach($s['items'] as $v){$n=min($rest,$v['quantity']);$covered[$v['id']]=($covered[$v['id']]??0)+$n;$rest-=$n;}}$supply=[];$deficit=0;$remaining=[];foreach($s['items'] as $v)$remaining[$v['id']]=max(0,$v['quantity']-($covered[$v['id']]??0));$zone=$c['passport']['timezone'];$lots=$s['tranches'];usort($lots,fn($a,$b)=>strcmp($a['expected_at']??'',$b['expected_at']??''));
 // Covered quantities include retained chains; their stock is not assigned twice.
 $skip=$covered;foreach($lots as $t){$id=$t['variant_id'];if(!isset($remaining[$id]))continue;$v=array_column($s['items'],null,'id')[$id];$available=max(0,(int)$t['received']);$wait=empty($t['cancelled'])?max(0,$t['promised']-$t['received']-($t['cancelled_quantity']??0)):0;$used=$skip[$id]??0;$n=min($used,$available);$available-=$n;$skip[$id]=$used-$n;if($skip[$id]>0){$n=min($skip[$id],$wait);$wait-=$n;$skip[$id]-=$n;}
  foreach([['available',$available,$start],['expected',$wait,$t['expected_at']?manufacturingTimestamp($t['expected_at'],$zone):$start]] as [$kind,$q,$at]){$q=min($q,$remaining[$id]);if(!$q)continue;$supply[]=['id'=>'supply-'.$t['id'].'-'.$kind.'-offset-'.($covered[$id]??0),'tranche_id'=>$t['id'],'variant_id'=>$id,'color'=>$v['color'],'size'=>$v['size'],'quantity'=>$q,'ready'=>max($start,$at),'dependency'=>null,'supply_kind'=>$kind];$remaining[$id]-=$q;}
 }
 foreach($remaining as $q)$deficit+=$q;return ['supply'=>$supply,'deficit'=>$deficit,'state'=>$s,'variants'=>$s['items']];
}
function preparationBatchIssued(array $c,array $o,string $batch):int{$row=one("SELECT SUM(quantity) AS q FROM preparation_movements WHERE company_id=? AND order_id=? AND batch_key=? AND kind='issue'",[$c['id'],$o['id'],$batch]);$used=(int)($row['q']??0);foreach(rows("SELECT released,dependencies,planning_meta FROM tasks WHERE company_id=? AND order_id=? AND state<>'cancelled' AND released>0",[$c['id'],$o['id']]) as $t){if(decode($t['dependencies']))continue;$m=decode($t['planning_meta']??null);if(($m['batch_id']??'legacy-'.$o['id'])===$batch)$used=max($used,(int)$t['released']);}return $used;}
function preparationIssueForTask(array $c,array $t,int $additional):void{
 if(!manufacturingAvailable())return;$o=one('SELECT * FROM orders WHERE id=? AND company_id=?',[$t['order_id'],$c['id']]);if(!$o)return;$o['route']=decode($o['route']);$m=is_array($t['planning_meta'])?$t['planning_meta']:decode($t['planning_meta']??null);if(!empty(decode($t['dependencies'])))return;$batch=$m['batch_id']??'legacy-'.$o['id'];$variant=$m['variant_id']??'variant-main';$issued=preparationBatchIssued($c,$o,$batch);$required=max(0,(int)$t['released']+$additional-$issued);if(!$required)return;$s=preparationState($c,$o);$balances=preparationBalances($c,$o);
 foreach($s['tranches'] as $lot){if($variant!=='variant-main'&&$lot['variant_id']!==$variant)continue;if(!empty($m['tranche_id'])&&$lot['id']!==$m['tranche_id'])continue;$b=$balances[$lot['id']]??['issued'=>0,'reserved'=>0];$own=0;foreach(rows('SELECT kind,quantity FROM preparation_movements WHERE company_id=? AND order_id=? AND tranche_id=? AND batch_key=?',[$c['id'],$o['id'],$lot['id'],$batch]) as $move)$own+=match($move['kind']){'reserve'=>(int)$move['quantity'],'issue','unreserve'=>-(int)$move['quantity'],default=>0};$own=max(0,$own);$free=max(0,$lot['received']-$b['issued']-$b['reserved']);$take=min($required,$free+$own);if(!$take)continue;if($take>$own)preparationMovement($c,$o,$lot['id'],$batch,'reserve',$take-$own,['task_id'=>$t['id']]);preparationMovement($c,$o,$lot['id'],$batch,'issue',$take,['task_id'=>$t['id'],'variant_id'=>$lot['variant_id']]);$required-=$take;if(!$required)break;}
 if($required)fail('SUPPLY_SHORTAGE: принятого совместимого кроя недостаточно для выпуска. Ожидание не разрешает фактический запуск.');
}
function cuttingSyncPreparation(array $c,array $o,array $cut):void{
 $record=preparationRecord($c,$o);$s=preparationUpgrade($record['state']??preparationDefault($c,$o),$c,$o);$prior=array_column($s['tranches'],null,'id');$s['tranches']=array_values(array_filter($s['tranches'],fn($t)=>($t['source_kind']??'')!=='cutting'||($t['source_ref']??'')!==$cut['id']));
 foreach($cut['calculation']['lays']??[] as $lay){$ex=$cut['state']['execution'][$lay['id']]??[];foreach($lay['output'] as $variant=>$quantity){$id='cut-'.$cut['id'].'-'.substr(hash('sha256',$lay['id'].'/'.$variant),0,24);$received=(int)($ex['transferred'][$variant]??0);$old=$prior[$id]['received']??0;if($received>$old)preparationMovement($c,$o,$id,'cutting-'.$cut['id'],'receipt',$received-$old,['cutting_plan_id'=>$cut['id'],'lay_id'=>$lay['id']]);$s['tranches'][]=['id'=>$id,'variant_id'=>$variant,'source_kind'=>'cutting','source_ref'=>$cut['id'],'source'=>'Раскрой · '.$cut['state']['name'],'unit'=>'комплект','composition'=>'Полный комплект проверенной раскладки','model'=>$o['product'],'pattern_version'=>$cut['state']['pattern_version'],'promised'=>$quantity,'received'=>$received,'expected_at'=>$lay['end']===null?null:(new DateTimeImmutable('@'.$lay['end']))->setTimezone(new DateTimeZone($c['passport']['timezone']))->format('Y-m-d H:i:s'),'cancelled'=>$cut['status']==='cancelled','cancelled_quantity'=>(int)($ex['scrap'][$variant]??0)];}}
 if(!$record||(($s['cost_mode']??'unknown')==='unknown'&&($s['manual_cost_cents']??null)===null))$s['cost_source']='detailed';preparationPersist($c,$o,$s,$record);
}

function preparationV74TaskAllowance(array $t):?int{
 if(decode($t['dependencies']))return null;$c=context();$o=one('SELECT * FROM orders WHERE id=? AND company_id=?',[$t['order_id'],$c['id']]);if(!$o)return 0;$o['route']=decode($o['route']);$m=is_array($t['planning_meta'])?$t['planning_meta']:decode($t['planning_meta']??null);$variant=$m['variant_id']??'variant-main';$batch=$m['batch_id']??'legacy-'.$o['id'];$s=preparationState($c,$o);$free=0;
 foreach($s['tranches'] as $lot)if(($variant==='variant-main'||$lot['variant_id']===$variant)&&(empty($m['tranche_id'])||$lot['id']===$m['tranche_id']))$free+=(int)($lot['free']??0);
 $own=one("SELECT SUM(CASE WHEN kind='reserve' THEN quantity WHEN kind IN ('issue','unreserve') THEN -quantity ELSE 0 END) q FROM preparation_movements WHERE company_id=? AND order_id=? AND batch_key=?",[$c['id'],$o['id'],$batch]);$issued=preparationBatchIssued($c,$o,$batch);return max(0,min((int)$t['quantity']-(int)$t['released'],$free+max(0,(int)($own['q']??0))+$issued-(int)$t['released']));
}
